import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"9、【小畜】 乾下巽上","description":"横渠易说 - 9、【小畜】 乾下巽上","frontmatter":{"title":"9、【小畜】 乾下巽上","description":"横渠易说 - 9、【小畜】 乾下巽上"},"headers":[],"relativePath":"zh/classics/hengqu/011.md","filePath":"zh/classics/hengqu/011.md"}'),l={name:"zh/classics/hengqu/011.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_9、【小畜】-乾下巽上" tabindex="-1">9、【小畜】 乾下巽上 <a class="header-anchor" href="#_9、【小畜】-乾下巽上" aria-label="Permalink to “9、【小畜】 乾下巽上”">​</a></h1><p>#小畜。亨。密云不雨，自我西郊。</p><h3 id="彖曰-小畜-柔得位而上下应之曰小畜。健而巽-刚中而志行-乃亨。-密云不雨-尚往也。-自我西郊-施未行也。" tabindex="-1">彖曰：小畜，柔得位而上下应之曰小畜。健而巽，刚中而志行，乃亨。“密云不雨”，尚往也。“自我西郊”，施未行也。 <a class="header-anchor" href="#彖曰-小畜-柔得位而上下应之曰小畜。健而巽-刚中而志行-乃亨。-密云不雨-尚往也。-自我西郊-施未行也。" aria-label="Permalink to “彖曰：小畜，柔得位而上下应之曰小畜。健而巽，刚中而志行，乃亨。“密云不雨”，尚往也。“自我西郊”，施未行也。”">​</a></h3><h3 id="象曰-风行天上-小畜-君子以懿文德。" tabindex="-1">象曰：风行天上，小畜，君子以懿文德。 <a class="header-anchor" href="#象曰-风行天上-小畜-君子以懿文德。" aria-label="Permalink to “象曰：风行天上，小畜，君子以懿文德。”">​</a></h3><p>“自我西郊”，刚阳之气进而不已也。</p><h3 id="初九-复自道-何其咎-吉。-象曰-复自道-其义吉也。" tabindex="-1">初九，复自道，何其咎，吉。 象曰：“复自道”，其义吉也。 <a class="header-anchor" href="#初九-复自道-何其咎-吉。-象曰-复自道-其义吉也。" aria-label="Permalink to “初九，复自道，何其咎，吉。 象曰：“复自道”，其义吉也。”">​</a></h3><p>以理而升，进之于应也。</p><h3 id="九二-牵复-吉。-象曰-牵复在中-亦不自失也。" tabindex="-1">九二，牵复，吉。 象曰：牵复在中，亦不自失也。 <a class="header-anchor" href="#九二-牵复-吉。-象曰-牵复在中-亦不自失也。" aria-label="Permalink to “九二，牵复，吉。 象曰：牵复在中，亦不自失也。”">​</a></h3><p>初反自道，三为说辐，二以汇征在中，故未为失。</p><h3 id="九三-舆说辐-夫妻反目。-象曰-夫妻反目-不能正室也。" tabindex="-1">九三，舆说辐，夫妻反目。 象曰：“夫妻反目”，不能正室也。 <a class="header-anchor" href="#九三-舆说辐-夫妻反目。-象曰-夫妻反目-不能正室也。" aria-label="Permalink to “九三，舆说辐，夫妻反目。 象曰：“夫妻反目”，不能正室也。”">​</a></h3><p>近而相比，故说辐而不能进，反为柔制，故曰反目；非其偶也，故不能正其室。</p><h3 id="六四-有孚血去惕出-无咎。-象曰-有孚惕出-上合志也。" tabindex="-1">六四，有孚血去惕出，无咎。 象曰：“有孚惕出”，上合志也。 <a class="header-anchor" href="#六四-有孚血去惕出-无咎。-象曰-有孚惕出-上合志也。" aria-label="Permalink to “六四，有孚血去惕出，无咎。 象曰：“有孚惕出”，上合志也。”">​</a></h3><p>以阴居阴，其体不躁，故曰“有孚”。能上比于五，与之合志，虽为群下所侵，被伤而去，怀惧而出，于义无咎。</p><h3 id="九五-有孚挛如-富以其邻。-象曰-有孚挛如-不独富也。" tabindex="-1">九五，有孚挛如，富以其邻。 象曰：“有孚挛如”，不独富也。 <a class="header-anchor" href="#九五-有孚挛如-富以其邻。-象曰-有孚挛如-不独富也。" aria-label="Permalink to “九五，有孚挛如，富以其邻。 象曰：“有孚挛如”，不独富也。”">​</a></h3><h3 id="上九-既雨既处-尚德载-妇贞厉。月几望-君子征-凶。-象曰-既雨既处-德积载也。-君子征凶-有所疑也。" tabindex="-1">上九，既雨既处，尚德载，妇贞厉。月几望，君子征，凶。 象曰：“既雨既处”，德积载也。“君子征凶”，有所疑也。 <a class="header-anchor" href="#上九-既雨既处-尚德载-妇贞厉。月几望-君子征-凶。-象曰-既雨既处-德积载也。-君子征凶-有所疑也。" aria-label="Permalink to “上九，既雨既处，尚德载，妇贞厉。月几望，君子征，凶。 象曰：“既雨既处”，德积载也。“君子征凶”，有所疑也。”">​</a></h3><p>六四为众阳之主，己能接之以信，挛如不疑，则亦为众所归，故曰“富以其邻”。</p>',16)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
